// ── Validación de skins al arrancar ────────────────────────────────
// Antes se ofrecían skins sin comprobar nada: si un archivo faltaba o
// una tira de animación no cuadraba con los fotogramas declarados, el
// personaje aparecía como un cuadro o el mapa se quedaba clavado. Lo
// que no pasa esta comprobación NO se ofrece: mejor una skin menos que
// una skin rota.

// Lee ancho y alto de un PNG sin dependencias: van en el bloque IHDR,
// en los bytes 16..24 de la cabecera.
function medidasPng(archivo) {
  const fd = fs.openSync(archivo, 'r')
  try {
    const buf = Buffer.alloc(24)
    if (fs.readSync(fd, buf, 0, 24, 0) < 24) return null
    if (buf.toString('ascii', 1, 4) !== 'PNG') return null
    return { ancho: buf.readUInt32BE(16), alto: buf.readUInt32BE(20) }
  } catch { return null } finally { fs.closeSync(fd) }
}

function validarSkins() {
  const problemas = []
  for (const s of SKINS) {
    const fallos = []
    for (const campo of ['file', 'portrait', 'avatar']) {
      if (!s[campo]) continue
      const ruta = path.join(ASSETS_DIR, 'skins', s[campo])
      if (!fs.existsSync(ruta)) { fallos.push(`falta ${s[campo]}`); continue }
      const m = medidasPng(ruta)
      if (!m) fallos.push(`${s[campo]} no es un PNG válido`)
      else if (m.ancho < 16 || m.alto < 16) fallos.push(`${s[campo]} es demasiado pequeño`)
    }
    // La tira de animación debe cuadrar EXACTAMENTE con lo declarado:
    // si no, el motor dibuja recortes con trozos de otros fotogramas.
    const w = s.sprites && s.sprites.walk
    if (w) {
      const ruta = path.join(ASSETS_DIR, 'skins', w.file)
      const m = fs.existsSync(ruta) ? medidasPng(ruta) : null
      if (!m) fallos.push(`falta la tira ${w.file}`)
      else if (m.ancho !== w.ancho * w.frames || m.alto !== w.alto) {
        fallos.push(`la tira ${w.file} mide ${m.ancho}x${m.alto} y se declaró ${w.ancho * w.frames}x${w.alto}`)
      }
    }
    if (fallos.length) { s.rota = true; problemas.push(`${s.id}: ${fallos.join(', ')}`) }
  }
  if (problemas.length) {
    console.error('\n⚠️  Skins retiradas por estar rotas:')
    for (const p of problemas) console.error('    · ' + p)
    console.error('')
  }
  return problemas
}

validarSkins()

// Solo entran al catálogo las skins que superaron la validación
const SKIN_IDS = new Set(SKINS.filter(s => !s.rota).map(s => s.id))
const DEFAULT_SKIN = 'aventurero'
const HEX_RE = /^#[0-9a-fA-F]{6}$/
const PALETTE_KEYS = ['skin', 'hair', 'outfit', 'accent']

function skinById(id) { return SKINS.find(s => s.id === id && !s.rota) || null }

function skinUnlocked(skin, char) {
  if (!skin) return false
  if (skin.unlock === 'default') return true
  if (skin.unlock === 'locked') return false
  const m = /^level:(\d+)$/.exec(skin.unlock || '')
  if (m) return (char?.level || 1) >= Number(m[1])
  return false
}

// Devuelve una apariencia válida a partir de lo que mande el cliente.
// Nunca confía en el cuerpo de la petición: recorta y sustituye.
function sanitizeAppearance(input, char) {
  const out = { skinId: DEFAULT_SKIN, palette: {}, title: null }
  const req = input && typeof input === 'object' ? input : {}
  // El personaje subido por el jugador es una skin más, pero solo
  // existe si de verdad tiene una imagen guardada.
  if (req.skinId === 'propio' && char && char.personajePropio) {
    return { skinId: 'propio', palette: {}, title: null }
  }
  const skin = SKIN_IDS.has(req.skinId) ? skinById(req.skinId) : skinById(DEFAULT_SKIN)
  out.skinId = skinUnlocked(skin, char) ? skin.id : DEFAULT_SKIN
  const base = skinById(out.skinId)
  for (const k of PALETTE_KEYS) {
    const v = req.palette && req.palette[k]
    out.palette[k] = (base.tint && typeof v === 'string' && HEX_RE.test(v)) ? v : base.palette[k]
  }
  return out
}

function skinPublic(s, char) {
  return {
    id: s.id, name: s.name, lore: s.lore, emoji: s.emoji,
    image: s.file ? `/assets/skins/${s.file}` : null,
    // Variantes ligeras: si no existen se cae a la imagen grande
    portrait: s.portrait ? `/assets/skins/${s.portrait}` : (s.file ? `/assets/skins/${s.file}` : null),
    avatar: s.avatar ? `/assets/skins/${s.avatar}` : (s.portrait ? `/assets/skins/${s.portrait}` : (s.file ? `/assets/skins/${s.file}` : null)),
    palette: s.palette, tint: !!s.tint, unlock: s.unlock,
    // Las ilustraciones con fondo opaco se ven como un cuadro si se
    // dibujan sobre el mundo: en el mapa se usa el emoji.
    usableEnMapa: !s.fondoOpaco,
    sprites: s.sprites
      ? Object.fromEntries(Object.entries(s.sprites).map(([k, v]) => [k, { ...v, url: `/assets/skins/${v.file}` }]))
      : null,
    unlocked: skinUnlocked(s, char),
  }
}


// ═══════════════════════════════════════════════════════════════════
//  INVITACIONES (beta cerrada)
//
//  Para qué: cuando el juego esté en internet vas a querer meter a diez
//  personas concretas, no a quien pase por ahí. Con INVITE_ONLY=1 el
//  registro exige un código; sin esa variable todo funciona como antes
//  y esto no molesta.
//
//  Además sirve para saber QUIÉN es cada quien en la analítica: cada
//  código lleva una etiqueta ("discord", "amigos", "reddit") y queda
//  registrada en el jugador, así se puede ver qué grupo se queda y
//  cuál se va.
//
//  Uso:
//    INVITE_ONLY=1 ADMIN_TOKEN=... node criptomundo.js
//    node invitaciones.js crear 10 --etiqueta=discord
// ═══════════════════════════════════════════════════════════════════
const INVITE_ONLY = process.env.INVITE_ONLY === '1'

store.invites = store.invites || {}   // código → { etiqueta, usos, maxUsos, creadoEn, usadoPor[] }

// Sin caracteres que se confundan al dictarlos por voz o chat (0/O, 1/I).
const INVITE_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

function generarCodigo() {
  const bytes = crypto.randomBytes(10)
  let out = ''
  for (let i = 0; i < 10; i++) {
    out += INVITE_ALPHABET[bytes[i] % INVITE_ALPHABET.length]
    if (i === 4) out += '-'
  }
  return out
}

function crearInvitaciones(cantidad, etiqueta, maxUsos) {
  const n = Math.max(1, Math.min(200, Math.floor(cantidad) || 1))
  const usos = Math.max(1, Math.min(500, Math.floor(maxUsos) || 1))
  const tag = String(etiqueta || 'general').slice(0, 32).replace(/[^\w\-áéíóúñÁÉÍÓÚÑ ]/g, '')
  const creados = []
  for (let i = 0; i < n; i++) {
    let codigo
    do { codigo = generarCodigo() } while (store.invites[codigo])
    store.invites[codigo] = { etiqueta: tag, usos: 0, maxUsos: usos, creadoEn: new Date().toISOString(), usadoPor: [] }
    creados.push(codigo)
  }
  audit('invites_create', 'admin', { cantidad: n, etiqueta: tag, maxUsos: usos })
  persist()
  return creados
}

function invitacionValida(codigo) {
  const inv = store.invites[String(codigo || '').trim().toUpperCase()]
  if (!inv) return { ok: false, error: 'Código de invitación no válido' }
  if (inv.usos >= inv.maxUsos) return { ok: false, error: 'Ese código ya se ha usado' }
  return { ok: true, inv }
}

function consumirInvitacion(codigo, username) {
  const key = String(codigo || '').trim().toUpperCase()
  const inv = store.invites[key]
  if (!inv) return null
  inv.usos += 1
  inv.usadoPor.push({ username, en: new Date().toISOString() })
  audit('invite_used', username, { codigo: key, etiqueta: inv.etiqueta })
  return inv
}

function resumenInvitaciones() {
  const lista = Object.entries(store.invites).map(([codigo, i]) => ({
    codigo, etiqueta: i.etiqueta, usos: i.usos, maxUsos: i.maxUsos,
    creadoEn: i.creadoEn, usadoPor: i.usadoPor.map(u => u.username),
  }))
  const porEtiqueta = {}
  for (const i of lista) {
    porEtiqueta[i.etiqueta] = porEtiqueta[i.etiqueta] || { emitidos: 0, usados: 0 }
    porEtiqueta[i.etiqueta].emitidos += 1
    if (i.usos > 0) porEtiqueta[i.etiqueta].usados += 1
  }
  return {
    inviteOnly: INVITE_ONLY,
    total: lista.length,
    usados: lista.filter(i => i.usos > 0).length,
    libres: lista.filter(i => i.usos < i.maxUsos).length,
    porEtiqueta,
    invitaciones: lista.sort((a, b) => a.creadoEn < b.creadoEn ? 1 : -1),
  }
}


// ═══════════════════════════════════════════════════════════════════
//  PERSONAJE PROPIO
//
//  Permite subir una imagen y usarla como personaje. El problema que
//  hay que evitar está claro por experiencia propia: en la v10 metimos
//  dos ilustraciones con el fondo incrustado y el personaje se veía
//  como un cuadro sobre el mapa. Con imágenes de desconocidos eso
//  pasaría siempre.
//
//  Por eso el recorte a círculo con fondo transparente lo hace el
//  navegador ANTES de subir (ver la página de perfil), y aquí se
//  comprueba que lo que llega es de verdad lo que se pidió:
//
//    · PNG auténtico (se miran los bytes, no la extensión ni el
//      nombre que diga el cliente)
//    · dimensiones dentro de rango y cuadrada
//    · peso máximo
//    · una imagen por jugador; subir otra sustituye la anterior
//
//  Si algo no cuadra, se rechaza con un motivo concreto y el jugador
//  se queda con la skin que tuviera. Nunca se guarda a medias.
// ═══════════════════════════════════════════════════════════════════

const SUBIDA_MAX_BYTES = 512 * 1024      // medio mega ya recortado
const SUBIDA_MIN_PX = 48
const SUBIDA_MAX_PX = 512
const DIR_PROPIOS = path.join(ASSETS_DIR, 'propios')

// Firma PNG: 8 bytes fijos. Es lo que distingue un PNG de un archivo
// renombrado a .png, que es el truco más viejo del mundo.
const FIRMA_PNG = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])

function validarPng(buf) {
  if (buf.length < 24) return { error: 'El archivo está incompleto' }
  if (!buf.subarray(0, 8).equals(FIRMA_PNG)) return { error: 'Solo se aceptan imágenes PNG' }
  if (buf.toString('ascii', 12, 16) !== 'IHDR') return { error: 'El PNG está corrupto' }
  const ancho = buf.readUInt32BE(16)
  const alto = buf.readUInt32BE(20)
  if (ancho < SUBIDA_MIN_PX || alto < SUBIDA_MIN_PX) return { error: `Mínimo ${SUBIDA_MIN_PX}×${SUBIDA_MIN_PX} píxeles` }
  if (ancho > SUBIDA_MAX_PX || alto > SUBIDA_MAX_PX) return { error: `Máximo ${SUBIDA_MAX_PX}×${SUBIDA_MAX_PX} píxeles` }
  if (ancho !== alto) return { error: 'La imagen debe ser cuadrada' }
  // El canal alfa está en el byte 25 (color type 6 = RGBA, 4 = gris+alfa).
  // Sin transparencia el personaje se vería como un cuadrado en el mapa.
  const tipoColor = buf[25]
  if (tipoColor !== 6 && tipoColor !== 4) return { error: 'La imagen debe tener transparencia (se recorta en el navegador)' }
  return { ancho, alto }
}

function guardarPersonajePropio(player, dataUrl) {
  const char = player.character
  if (typeof dataUrl !== 'string') return { error: 'No llegó ninguna imagen', code: 400 }

  const m = /^data:image\/png;base64,([A-Za-z0-9+/=]+)$/.exec(dataUrl.trim())
  if (!m) return { error: 'Formato no admitido: debe ser un PNG', code: 400 }

  let buf
  try { buf = Buffer.from(m[1], 'base64') } catch { return { error: 'La imagen no se pudo leer', code: 400 } }
  if (buf.length > SUBIDA_MAX_BYTES) {
    return { error: `La imagen pesa ${Math.round(buf.length / 1024)} KB y el máximo son ${SUBIDA_MAX_BYTES / 1024} KB`, code: 413 }
  }

  const v = validarPng(buf)
  if (v.error) return { error: v.error, code: 400 }

  try {
    fs.mkdirSync(DIR_PROPIOS, { recursive: true })
    // Nombre derivado del contenido: subir dos veces lo mismo no
    // acumula archivos, y el nombre no depende de nada que mande el
    // cliente (que podría intentar meter rutas dentro).
    const hash = crypto.createHash('sha256').update(buf).digest('hex').slice(0, 16)
    const archivo = `${player.username.toLowerCase().replace(/[^a-z0-9]/g, '')}-${hash}.png`
    const destino = path.join(DIR_PROPIOS, archivo)
    if (!destino.startsWith(DIR_PROPIOS)) return { error: 'Ruta inválida', code: 400 }

    // Se escribe temporal y se renombra, como el resto de escrituras:
    // así nunca queda un PNG a medias que rompa la pantalla.
    const tmp = destino + '.tmp'
    fs.writeFileSync(tmp, buf)
    fs.renameSync(tmp, destino)

    // Borrar la anterior para no dejar basura acumulándose
    const previo = char.personajePropio && char.personajePropio.archivo
    if (previo && previo !== archivo) {
      try { fs.unlinkSync(path.join(DIR_PROPIOS, previo)) } catch {}
    }

    char.personajePropio = {
      archivo, ancho: v.ancho, alto: v.alto,
      bytes: buf.length, subidoEn: new Date().toISOString(),
    }
    char.appearance = char.appearance || {}
    char.appearance.skinId = 'propio'
    audit('personaje_propio', char.name, { archivo, bytes: buf.length, medidas: `${v.ancho}x${v.alto}` })
    persist()
    return { success: true, personaje: skinPropiaDe(char) }
  } catch (e) {
    console.error('[subida]', e.message)
    return { error: 'No se pudo guardar la imagen', code: 500 }
  }
}

function quitarPersonajePropio(player) {
  const char = player.character
  if (!char.personajePropio) return { error: 'No tienes ningún personaje subido', code: 404 }
  try { fs.unlinkSync(path.join(DIR_PROPIOS, char.personajePropio.archivo)) } catch {}
  char.personajePropio = null
  if (char.appearance && char.appearance.skinId === 'propio') {
    char.appearance = sanitizeAppearance({ skinId: DEFAULT_SKIN }, char)
  }
  persist()
  return { success: true, appearance: char.appearance }
}

// Se presenta como una skin más para que el resto del juego (creador,
// perfil, barra superior, mapa) no necesite saber que es especial.
function skinPropiaDe(char) {
  if (!char || !char.personajePropio) return null
  const url = `/assets/propios/${char.personajePropio.archivo}`
  return {
    id: 'propio', name: 'Mi personaje', lore: 'La imagen que subiste, recortada en círculo.',
    emoji: '🖼️', image: url, portrait: url, avatar: url,
    palette: {}, tint: false, unlock: 'default', unlocked: true,
    usableEnMapa: true, sprites: null, propia: true,
    subidoEn: char.personajePropio.subidoEn,
  }
}


