// ═══════════════════════════════════════════════════════════════════
//  (Las mazmorras viven en 59-mazmorras.js desde la v22)
//
//  Aquí había un sistema de mazmorras de "pulsar Avanzar" con su
//  catálogo, sus DungeonRun y sus tiempos mínimos. Se sustituyó por el
//  de salas y combate real. Antes de retirarlo se comprobó que ninguna
//  página lo llamaba: el único resto era un puente huérfano en el
//  launcher que nadie invocaba desde que se reescribió la pantalla.
//
//  Se retira en vez de dejarlo desconectado porque código muerto que
//  parece vivo ya nos costó un diagnóstico equivocado: el doctor
//  probaba este endpoint y no el que usa el juego.
// ═══════════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════════
//  PvP — resultado determinado por el servidor (sin apuestas reales)
// ═══════════════════════════════════════════════════════════════════
const PVP_MAX_GOLD_WAGER = 2000     // apuesta simbólica de oro, nunca CGRID
function simulatePvp(char, opponent, seed) {
  const rng = makeRng(seed)
  const a = effectiveStats(char)
  const b = opponent.stats
  let hpA = a.maxHp, hpB = b.maxHp
  const rounds = []
  for (let i = 0; i < 40 && hpA > 0 && hpB > 0; i++) {
    const dmgA = Math.max(1, Math.floor((a.strength + a.intelligence + a.agility) * (0.7 + rng() * 0.6) - b.defense * 0.8))
    hpB -= dmgA
    if (hpB <= 0) { rounds.push({ turn: i, dmgA, dmgB: 0 }); break }
    const dmgB = Math.max(1, Math.floor((b.strength + b.intelligence + b.agility) * (0.7 + rng() * 0.6) - a.defense * 0.8))
    hpA -= dmgB
    rounds.push({ turn: i, dmgA, dmgB })
  }
  return { win: hpA > 0 && hpB <= 0, hpA: Math.max(0, hpA), hpB: Math.max(0, hpB), rounds }
}

function botOpponent(rating, level) {
  const scale = Math.max(0.6, rating / 1400)
  return {
    name: ['VoidWalker', 'IronForge', 'DragonHeart', 'FrostMage', 'NightBlade'][randInt(0, 4)],
    rating, level,
    stats: {
      strength: Math.floor(18 * scale + level * 2), intelligence: Math.floor(18 * scale + level * 2),
      agility: Math.floor(16 * scale + level * 2), defense: Math.floor(20 * scale + level * 2),
      maxHp: Math.floor(700 * scale + level * 45),
    },
  }
}

function runPvpMatch(char, wagerGold) {
  char.pvpLast = char.pvpLast || 0
  if (now() - char.pvpLast < 5000) return { error: 'Espera antes de otro combate', code: 429 }
  char.pvpLast = now()
  const wager = Math.min(Math.max(0, Math.floor(wagerGold || 0)), PVP_MAX_GOLD_WAGER, Math.floor(char.gold * 0.2))
  const opp = botOpponent(Math.max(800, (char.pvpRating || 1200) + randInt(-120, 120)), char.level)
  const seed = crypto.randomBytes(8).toString('hex')
  const sim = simulatePvp(char, opp, seed)
  const expected = 1 / (1 + Math.pow(10, (opp.rating - char.pvpRating) / 400))
  const K = 32
  const delta = Math.round(K * ((sim.win ? 1 : 0) - expected))
  char.pvpRating = Math.max(800, (char.pvpRating || 1200) + delta)
  if (sim.win) { char.pvpWins = (char.pvpWins || 0) + 1; char.gold += wager }
  else { char.pvpLosses = (char.pvpLosses || 0) + 1; char.gold = Math.max(0, char.gold - wager) }
  const match = { id: nextId('pvp'), owner: char.id, seed, opponent: opp.name, result: sim.win ? 'win' : 'loss', delta, wager, at: new Date().toISOString() }
  store.pvpMatches[match.id] = match
  audit('pvp_match', char.name, { result: match.result, delta, wager, opponent: opp.name, seed })
  track('pvp_match', char.name)
  step(char.name, 'first_pvp')
  persist()
  const st = effectiveStats(char)
  return {
    success: true, matchId: match.id, opponent: opp.name, opponentRating: opp.rating,
    result: match.result, newRating: char.pvpRating, ratingChange: delta,
    newGold: char.gold, newCgrid: char.cgrid, wager, rounds: sim.rounds.length, levelUps: [],
    // El combate, no solo el veredicto.
    //
    // Se devolvían únicamente el resultado y el número de asaltos, así
    // que la pantalla solo podía decir "has ganado". El servidor ya
    // calcula el intercambio asalto a asalto —lo necesita para saber
    // quién gana—, y tirarlo obliga a quien dibuje a inventarse la
    // pelea o a no enseñarla. Aquí va tal cual, igual que el guion del
    // combate por turnos: el cliente lo REPRODUCE, no lo decide.
    duelo: {
      semilla: seed,
      tu: { nombre: char.name, nivel: char.level, hpMax: st.maxHp, rating: char.pvpRating - delta },
      rival: { nombre: opp.name, nivel: opp.level, hpMax: opp.stats.maxHp, rating: opp.rating },
      asaltos: sim.rounds,
      hpFinalTuyo: sim.hpA, hpFinalRival: sim.hpB,
    },
  }
}

// ═══════════════════════════════════════════════════════════════════
//  MERCADO — escrow, ownership, comisión, compra atómica
// ═══════════════════════════════════════════════════════════════════
const MARKET_MAX_PRICE = 10_000_000
function seedMarket() {
  if (store.marketListings.length) return
  const seeds = [
    ['sword_alba', 2, 340, 'ArkaneX'], ['crystal', 3, 420, 'IronForge'], ['iron_ore', 20, 15, 'StarDust'],
    ['potion_hp', 10, 22, 'FrostMage'], ['arcane_orb', 1, 1800, 'VoidWalker'], ['elven_bow', 1, 950, 'NightBlade'],
    ['thunder_staff', 1, 2800, 'DragonHeart'], ['herb', 15, 5, 'Elara'],
  ]
  for (const [itemId, qty, price, seller] of seeds) {
    const t = template(itemId)
    store.marketListings.push({
      id: nextId('lst'), sellerId: 'npc_' + seller, seller: { name: seller }, npc: true,
      itemId, quantity: qty, pricePerUnit: price, currency: 'gold',
      item: { itemId, name: t.name, icon: t.icon, rarity: t.rarity, type: t.type },
      status: 'ACTIVE', createdAt: new Date().toISOString(),
      expiresAt: new Date(Date.now() + 7 * 86400000).toISOString(),
    })
  }
}

// ── Caducidad: el escrow tiene que volver ──────────────────────────
//
// Al publicar, el objeto SALE del inventario (línea del removeItem, más
// abajo). Cancelar lo devuelve; vender se lo entrega al comprador.
// Caducar no hacía ninguna de las tres cosas: el objeto se quedaba
// dentro de la publicación para siempre y el vendedor lo perdía sin que
// nadie se lo dijera.
//
// Y había un segundo lado. El estado solo pasaba a EXPIRED dentro de
// buyListing, o sea SOLO si alguien intentaba comprarla. Una publicación
// caducada a la que nadie picara seguía saliendo en la tienda como
// comprable, porque la tienda filtra por status === 'ACTIVE'. Se veía
// como una oferta buena, se pulsaba, y contestaba que estaba caducada.
//
// Las publicaciones de arranque (npc: true) nunca salieron del
// inventario de nadie, así que no hay nada que devolverles.
function caducarListing(l) {
  if (!l || l.status !== 'ACTIVE') return false
  if (new Date(l.expiresAt).getTime() >= now()) return false
  l.status = 'EXPIRED'
  l.escrowDevuelto = !!l.npc
  devolverEscrow(l)
  audit('market_expire', (l.seller && l.seller.name) || '?',
        { listingId: l.id, itemId: l.itemId, qty: l.quantity, devuelto: !!l.escrowDevuelto })
  return true
}

// Se separa del paso anterior porque PUEDE FALLAR: si al vendedor no le
// cabe en el inventario, o no está cargado, se deja pendiente y se
// reintenta en el siguiente barrido. Tirar el objeto sería el mismo
// fallo que se está arreglando.
//
// El escrowDevuelto sin poner cuenta como "sin devolver": las partidas
// guardadas antes de esto traen caducadas a las que nunca se les
// devolvió nada, y el primer barrido se las devuelve.
function devolverEscrow(l) {
  if (!l || l.escrowDevuelto) return false
  const p = Object.values(store.players).find(x => x.character.id === l.sellerId)
  if (!p) return false
  if (!addItem(p.character, l.itemId, l.quantity, 'mercado')) return false
  l.escrowDevuelto = true
  return true
}

function barrerMercado() {
  let tocado = false
  for (const l of store.marketListings) {
    if (caducarListing(l)) tocado = true
    else if (l.status === 'EXPIRED' && !l.escrowDevuelto && devolverEscrow(l)) tocado = true
  }
  if (tocado) persist()
  return tocado
}

// Una vez por minuto. Nadie tiene que entrar en la tienda para que a un
// vendedor le vuelva lo suyo.
setInterval(barrerMercado, 60_000).unref?.()

function createListing(char, itemId, quantity, pricePerUnit) {
  const t = template(itemId)
  if (!t) return { error: 'Objeto desconocido', code: 400 }
  if (t.tradeable === false) return { error: 'Objeto no comerciable', code: 400 }
  const qty = intIn(quantity, 1, 999)
  const price = intIn(pricePerUnit, 1, MARKET_MAX_PRICE)
  if (!qty || !price) return { error: 'Cantidad o precio inválido', code: 400 }
  if (countItem(char, itemId) < qty) return { error: 'Ítems insuficientes', code: 400 }
  const mine = store.marketListings.filter(l => l.sellerId === char.id && l.status === 'ACTIVE').length
  if (mine >= 20) return { error: 'Máximo 20 publicaciones activas', code: 429 }
  removeItem(char, itemId, qty, 'mercado')   // ESCROW: el objeto sale del inventario
  const listing = {
    id: nextId('lst'), sellerId: char.id, seller: { name: char.name },
    itemId, quantity: qty, pricePerUnit: price, currency: 'gold',
    item: { itemId, name: t.name, icon: t.icon, rarity: t.rarity, type: t.type },
    status: 'ACTIVE', createdAt: new Date().toISOString(),
    expiresAt: new Date(Date.now() + 2 * 86400000).toISOString(),
  }
  store.marketListings.push(listing)
  audit('market_list', char.name, { listingId: listing.id, itemId, qty, price })
  persist()
  return { listing }
}

// Sin await en el cuerpo → la operación es atómica en el loop de Node
function buyListing(char, listingId, quantity) {
  const listing = store.marketListings.find(l => l.id === listingId)
  if (!listing) return { error: 'Publicación no encontrada', code: 404 }
  if (listing.status !== 'ACTIVE') return { error: 'Publicación no disponible', code: 409 }
  if (caducarListing(listing)) return { error: 'Publicación expirada', code: 409 }
  if (listing.sellerId === char.id) return { error: 'No puedes comprar tu propia publicación', code: 400 }
  const qty = intIn(quantity, 1, listing.quantity)
  if (!qty) return { error: 'Cantidad inválida', code: 400 }
  // EL PRECIO SIEMPRE SALE DEL LISTING, NUNCA DEL CLIENTE
  const cost = listing.pricePerUnit * qty
  if (char.gold < cost) return { error: 'Oro insuficiente', code: 400 }

  char.gold -= cost
  listing.quantity -= qty
  if (listing.quantity <= 0) listing.status = 'SOLD'
  const added = addItem(char, listing.itemId, qty, 'mercado')
  if (!added) { char.gold += cost; listing.quantity += qty; listing.status = 'ACTIVE'; return { error: 'Inventario lleno', code: 400 } }

  const fee = Math.floor(cost * ECONOMY.MARKET_FEE)
  store.economy.goldBurned += fee
  const seller = Object.values(store.players).find(p => p.character.id === listing.sellerId)
  if (seller) seller.character.gold += (cost - fee)

  const tx = { id: nextId('tx'), listingId, buyer: char.name, seller: listing.seller.name, itemId: listing.itemId, quantity: qty, unitPrice: listing.pricePerUnit, total: cost, fee, at: new Date().toISOString() }
  store.marketTransactions.push(tx)
  // El historial completo no cabe en memoria para siempre: se conservan
  // las últimas 2000, que es lo que además se vuelca a disco.
  if (store.marketTransactions.length > 2000) store.marketTransactions.splice(0, 500)
  audit('market_buy', char.name, tx)
  trackCurrency(char.name, 'gold', -cost, 'market_buy')
  if (seller) trackCurrency(seller.character.name, 'gold', cost - fee, 'market_sale')
  track('market_buy', char.name)
  step(char.name, 'first_market_buy')
  persist()
  return { success: true, totalCost: cost, fee, currency: 'gold', transaction: tx, newGold: char.gold }
}

function cancelListing(char, listingId) {
  const l = store.marketListings.find(x => x.id === listingId)
  if (!l) return { error: 'No encontrada', code: 404 }
  if (l.sellerId !== char.id) return { error: 'No es tu publicación', code: 403 }
  if (l.status !== 'ACTIVE') return { error: 'No está activa', code: 409 }
  l.status = 'CANCELLED'
  addItem(char, l.itemId, l.quantity, 'mercado')   // devuelve el escrow
  audit('market_cancel', char.name, { listingId })
  persist()
  return { success: true }
}

// ═══════════════════════════════════════════════════════════════════
//  GREMIOS — permisos, capacidad, coste, tesorería
// ═══════════════════════════════════════════════════════════════════
const GUILD_CREATE_COST = 5000
const GUILD_ROLES = { LEADER: 3, OFFICER: 2, MEMBER: 1 }
function seedGuilds() {
  if (Object.keys(store.guilds).length) return
  const base = [
    ['Guardianes del Nexo', '[GDN]', '🌀', 12, 'ArkaneX'],
    ['Legión de Hierro', '[LDH]', '⚔️', 9, 'IronLord'],
    ['Orden Oscura', '[OO]', '💀', 6, 'DarkMage'],
  ]
  for (const [name, tag, emblem, level, leader] of base) {
    const id = nextId('g')
    store.guilds[id] = { id, name, tag, emblem, level, leader, desc: '', members: [{ name: leader, role: 'LEADER', joinedAt: new Date().toISOString() }], maxMembers: 20 + level, treasury: { gold: 0, cgrid: 0 }, xp: 0, wins: 0, losses: 0, draws: 0, founded: new Date().toISOString().slice(0, 10), npc: true }
  }
}
function guildPublic(g) {
  return { id: g.id, name: g.name, tag: g.tag, emblem: g.emblem, level: g.level, leader: g.leader, desc: g.desc, members: g.members.length, maxMembers: g.maxMembers, treasury: g.treasury, wins: g.wins, losses: g.losses, draws: g.draws, founded: g.founded, power: g.level * 12000 + g.members.length * 1500 }
}
function guildRole(g, char) {
  const m = g.members.find(x => x.name === char.name)
  return m ? m.role : null
}


// ═══════════════════════════════════════════════════════════════════
//  PRIMEROS PASOS
//
//  Por qué existe: el embudo mostraba que solo la mitad de los
//  jugadores llegaba a aceptar una misión y el 40 % a completarla,
//  aunque el juego lo permitía desde el minuto uno. No era un problema
//  de dificultad sino de que nadie sabía qué hacer al entrar.
//
//  Esta lista NO es un tutorial que bloquea: es una guía opcional que
//  se marca sola con lo que el jugador ya hace. El estado sale de los
//  mismos eventos que alimentan la telemetría, así que no hay una
//  segunda fuente de verdad que se pueda desincronizar.
//
//  Para añadir un paso: una entrada aquí y ya aparece en la interfaz.
//    id      identificador estable
//    titulo  qué se le pide al jugador
//    pista   cómo hacerlo, en una línea
//    modulo  a qué pantalla lleva el botón
//    evento  paso del embudo que lo da por hecho
//    oro     recompensa al reclamarlo
// ═══════════════════════════════════════════════════════════════════
const PRIMEROS_PASOS = [
  { id: 'p_combate', titulo: 'Gana tu primer combate', pista: 'Entra en Combate, elige la Araña Venenosa y ataca hasta vencerla.', modulo: 'combat', evento: 'first_kill', oro: 100 },
  // Estos dos van justo después del primer combate y antes que nada más,
  // porque son los que deciden si el juego se vive como difícil o como
  // justo. El banco de balance lo mide: bloqueando el golpe anunciado y
  // bebiendo por debajo de un tercio no se pierde ni una pelea en todo
  // el juego. Sin saberlo, un nivel 1 muere cuatro veces antes del 3.
  { id: 'p_bloquear', titulo: 'Bloquea un golpe anunciado', pista: 'Cuando el enemigo avise de un golpe fuerte, pulsa Bloquear 🛡️: encaja un tercio del daño en vez de todo.', modulo: 'combat', evento: 'first_block', oro: 120 },
  { id: 'p_pocion', titulo: 'Bébete una poción peleando', pista: 'No hace falta esperar a morir: en combate, el botón 🧪 cura sin perder el turno de atacar.', modulo: 'combat', evento: 'first_potion', oro: 120 },
  { id: 'p_mision', titulo: 'Acepta una misión', pista: 'En Misiones, habla con Lyria la Alquimista y acepta "Cosecha de Hierbas".', modulo: 'misiones', evento: 'first_quest_accept', oro: 100 },
  { id: 'p_taller', titulo: 'Fabrica algo en el taller', pista: 'En Taller, la Poción de Vida solo necesita hierbas y agua.', modulo: 'crafting', evento: 'first_craft', oro: 150 },
  { id: 'p_nivel2', titulo: 'Alcanza el nivel 2', pista: 'Un par de combates bastan.', modulo: 'combat', evento: 'level_2', oro: 150 },
  { id: 'p_entrega', titulo: 'Entrega una misión completa', pista: 'El progreso avanza solo con acciones reales; cuando esté al completo, entrégala al NPC.', modulo: 'misiones', evento: 'first_quest_complete', oro: 250 },
  { id: 'p_mercado', titulo: 'Compra algo en el mercado', pista: 'En Mercado hay materiales baratos de otros jugadores.', modulo: 'mercado', evento: 'first_market_buy', oro: 200 },
  { id: 'p_recolectar', titulo: 'Recoge agua del pozo', pista: 'En Huerto, el pozo del pueblo da agua para las pociones.', modulo: 'huerto', evento: 'first_gather', oro: 120 },
  { id: 'p_sembrar', titulo: 'Siembra y cosecha algo', pista: 'En Huerto, siembra una semilla y vuelve cuando haya crecido.', modulo: 'huerto', evento: 'first_harvest', oro: 200 },
  { id: 'p_arena', titulo: 'Gana un combate en la Arena', pista: 'En Arena se pelea moviéndose: acércate, apunta y golpea.', modulo: 'arena', evento: 'first_arena', oro: 300 },
  { id: 'p_mazmorra', titulo: 'Completa una mazmorra', pista: 'En Mazmorras eliges sala en cada piso. El botín solo se cobra si sales con vida.', modulo: 'mazmorras', evento: 'first_dungeon', oro: 500 },
]

const PASOS_POR_ID = new Map(PRIMEROS_PASOS.map(p => [p.id, p]))

function pasosDe(player) {
  const hechos = (store.analytics.users[player.username] || {}).steps || {}
  const reclamados = player.character.pasosReclamados || []
  return PRIMEROS_PASOS.map(p => ({
    id: p.id, titulo: p.titulo, pista: p.pista, modulo: p.modulo, oro: p.oro,
    hecho: !!hechos[p.evento],
    reclamado: reclamados.includes(p.id),
  }))
}

function resumenPasos(player) {
  const pasos = pasosDe(player)
  const hechos = pasos.filter(p => p.hecho).length
  const siguiente = pasos.find(p => !p.hecho) || null
  const porReclamar = pasos.filter(p => p.hecho && !p.reclamado).length
  return {
    pasos, total: pasos.length, hechos, porReclamar,
    siguiente: siguiente ? siguiente.id : null,
    completado: hechos === pasos.length,
  }
}

// Reclamar es explícito: el jugador ve la recompensa al pulsar, en vez
// de que le aparezca oro de la nada sin saber por qué.
function reclamarPaso(player, id) {
  const paso = PASOS_POR_ID.get(id)
  if (!paso) return { error: 'Paso desconocido', code: 404 }
  const hechos = (store.analytics.users[player.username] || {}).steps || {}
  if (!hechos[paso.evento]) return { error: 'Todavía no has completado ese paso', code: 400 }
  const char = player.character
  char.pasosReclamados = char.pasosReclamados || []
  if (char.pasosReclamados.includes(id)) return { error: 'Recompensa ya recibida', code: 409 }
  char.pasosReclamados.push(id)
  char.gold += paso.oro
  trackCurrency(char.name, 'gold', paso.oro, 'primeros_pasos')
  audit('primeros_pasos', char.name, { paso: id, oro: paso.oro })
  persist()
  return { success: true, oro: paso.oro, newGold: char.gold, resumen: resumenPasos(player) }
}


// ═══════════════════════════════════════════════════════════════════
//  MEDALLAS
//  Se calculan a partir de contadores reales del personaje; no se
//  guardan por separado para que no puedan desincronizarse de los
//  hechos. Si matas 50 monstruos, la medalla existe; si el contador
//  baja, deja de existir. Una sola fuente de verdad.
// ═══════════════════════════════════════════════════════════════════
const MEDALLAS = [
  { id: 'primera_sangre', nombre: 'Primera sangre',   icono: '🩸', desc: 'Derrota a tu primer enemigo',       mide: c => c.monstersKilled || 0, meta: 1 },
  { id: 'cazador',        nombre: 'Cazador',          icono: '🏹', desc: 'Derrota 50 enemigos',               mide: c => c.monstersKilled || 0, meta: 50 },
  { id: 'exterminador',   nombre: 'Exterminador',     icono: '💀', desc: 'Derrota 250 enemigos',              mide: c => c.monstersKilled || 0, meta: 250 },
  { id: 'matajefes',      nombre: 'Matajefes',        icono: '👑', desc: 'Derrota 5 jefes',                   mide: c => c.bossesKilled || 0, meta: 5 },
  { id: 'espeleologo',    nombre: 'Espeleólogo',      icono: '🏰', desc: 'Completa 3 mazmorras',              mide: c => c.dungeonsCleared || 0, meta: 3 },
  { id: 'veterano',       nombre: 'Veterano',         icono: '⭐', desc: 'Alcanza el nivel 10',               mide: c => c.level || 1, meta: 10 },
  { id: 'artesano',       nombre: 'Artesano',         icono: '⚒️', desc: 'Fabrica 25 objetos',                mide: c => c.objetosFabricados || 0, meta: 25 },
  { id: 'hortelano',      nombre: 'Hortelano',        icono: '🌾', desc: 'Cosecha 20 veces',                  mide: c => c.cosechas || 0, meta: 20 },
  { id: 'recolector',     nombre: 'Recolector',       icono: '🧺', desc: 'Reúne 200 recursos',                mide: c => c.recursosRecolectados || 0, meta: 200 },
  { id: 'explorador',     nombre: 'Explorador',       icono: '🗺️', desc: 'Visita las 6 zonas',               mide: c => (c.zonesVisited || []).length, meta: 6 },
  { id: 'mercader',       nombre: 'Mercader',         icono: '🪙', desc: 'Acumula 10.000 de oro',             mide: c => c.gold || 0, meta: 10000 },
  { id: 'duelista',       nombre: 'Duelista',         icono: '⚔️', desc: 'Gana 10 combates PvP',              mide: c => c.pvpWins || 0, meta: 10 },
]

function medallasDe(char) {
  return MEDALLAS.map(m => {
    const valor = m.mide(char)
    return {
      id: m.id, nombre: m.nombre, icono: m.icono, desc: m.desc,
      progreso: Math.min(valor, m.meta), meta: m.meta,
      conseguida: valor >= m.meta,
    }
  })
}

// Retrato completo del jugador con datos reales, sin nada inventado.
function perfilDe(player) {
  const c = player.character
  const st = effectiveStats(c)
  const medallas = medallasDe(c)
  const u = (store.analytics.users || {})[player.username] || {}
  return {
    nombre: c.name, clase: c.class, nivel: c.level,
    xp: c.xp, xpSiguiente: c.xpToNext,
    apariencia: c.appearance,
    creadoEn: c.createdAt,
    minutosJugados: Math.round(u.playMinutes || 0),
    diasActivos: (u.activeDays || []).length,
    estadisticas: {
      fuerza: st.strength, inteligencia: st.intelligence, agilidad: st.agility,
      defensa: st.defense, vidaMax: st.maxHp, manaMax: st.maxMp,
    },
    contadores: {
      bajas: c.monstersKilled || 0,
      jefes: c.bossesKilled || 0,
      mazmorras: c.dungeonsCleared || 0,
      muertes: c.muertes || 0,
      objetosFabricados: c.objetosFabricados || 0,
      recursosRecolectados: c.recursosRecolectados || 0,
      cosechas: c.cosechas || 0,
      consumiblesUsados: c.consumiblesUsados || 0,
      misionesCompletadas: (c.completedQuests || []).length,
      zonasVisitadas: (c.zonesVisited || []).length,
      pvp: { victorias: c.pvpWins || 0, derrotas: c.pvpLosses || 0, puntuacion: c.pvpRating || 1200 },
    },
    equipo: c.equipment || {},
    medallas,
    medallasConseguidas: medallas.filter(m => m.conseguida).length,
  }
}


// ═══════════════════════════════════════════════════════════════════
//  AVISOS DE LOS JUGADORES
//
//  Para qué: cuando alguien encuentre un fallo en la beta, lo va a
//  contar por Discord con la mitad del contexto ("no me funcionaba el
//  mercado, creo"). Este endpoint recoge el aviso con lo que importa
//  ya adjunto: página, versión, nivel del personaje y navegador.
//
//  Deliberadamente simple: un texto y su contexto. Sin categorías ni
//  campos obligatorios, porque un formulario largo no lo rellena nadie.
// ═══════════════════════════════════════════════════════════════════
store.feedback = store.feedback || []

const FEEDBACK_MAX = 500
const FEEDBACK_TIPOS = ['fallo', 'idea', 'otro']

function guardarAviso(player, body, req) {
  const texto = String(body.texto || '').trim().slice(0, 1500)
  if (texto.length < 3) return { error: 'Escribe algo más', code: 400 }

  const aviso = {
    id: nextId('fb'),
    tipo: FEEDBACK_TIPOS.includes(body.tipo) ? body.tipo : 'otro',
    texto: sanitize(texto),
    // Contexto que el jugador no tendría que escribir a mano
    pagina: sanitize(String(body.pagina || '').slice(0, 120)),
    version: VERSION,
    jugador: player ? sanitize(player.username) : null,
    nivel: player ? player.character.level : null,
    navegador: sanitize(String(req.headers['user-agent'] || '').slice(0, 200)),
    pantalla: sanitize(String(body.pantalla || '').slice(0, 20)),
    at: new Date().toISOString(),
    resuelto: false,
  }

  store.feedback.push(aviso)
  if (store.feedback.length > FEEDBACK_MAX) store.feedback.splice(0, 100)
  audit('feedback', aviso.jugador || 'anónimo', { tipo: aviso.tipo, id: aviso.id })
  persist()
  return { success: true, id: aviso.id }
}

function listarAvisos() {
  const porTipo = {}
  for (const a of store.feedback) porTipo[a.tipo] = (porTipo[a.tipo] || 0) + 1
  return {
    total: store.feedback.length,
    sinResolver: store.feedback.filter(a => !a.resuelto).length,
    porTipo,
    avisos: store.feedback.slice().reverse(),
  }
}

function marcarResuelto(id, resuelto) {
  const a = store.feedback.find(x => x.id === id)
  if (!a) return { error: 'Aviso no encontrado', code: 404 }
  a.resuelto = resuelto !== false
  persist()
  return { success: true, aviso: a }
}


// ═══════════════════════════════════════════════════════════════════
//  RECOLECCIÓN Y HUERTO
//
//  Dos agujeros reales del juego que esto tapa:
//
//  1. El AGUA solo existía en el inventario inicial (10 unidades) y en
//     el mercado. Ninguna criatura la soltaba y no había forma de
//     conseguirla: al gastarla, las pociones quedaban bloqueadas para
//     siempre. Lo mismo con el TRIGO, que hacía falta para el pan y no
//     lo daba absolutamente nada: esa receta era incompletable desde
//     el primer minuto.
//
//  2. No había ninguna actividad que no fuera pelear.
//
//  Los nodos de recolección son por zona y con enfriamiento propio de
//  cada jugador; el huerto es de tiempo real (se siembra, se espera de
//  verdad y se vuelve a cosechar).
// ═══════════════════════════════════════════════════════════════════

// ── Nodos de recolección ───────────────────────────────────────────
//   zona        dónde aparece
//   cooldownMs  espera por jugador y nodo
//   sueltan     [itemId, min, max, probabilidad]
const NODOS = [
  { id: 'pozo',      nombre: 'Pozo del pueblo',  icono: '🪣', zona: 'pueblo', cooldownMs: 60_000,
    descripcion: 'Sacar agua del pozo. Nunca se seca.',
    sueltan: [['water', 2, 4, 1]], xp: 5 },
  { id: 'rio',       nombre: 'Río del bosque',   icono: '🏞️', zona: 'forest', cooldownMs: 90_000,
    descripcion: 'Agua limpia y algún junco.',
    sueltan: [['water', 3, 5, 1], ['herb', 1, 2, 0.4]], xp: 8 },
  { id: 'herbario',  nombre: 'Claro de hierbas', icono: '🌿', zona: 'forest', cooldownMs: 120_000,
    descripcion: 'Hierba medicinal y semillas silvestres.',
    sueltan: [['herb', 2, 4, 1], ['semilla_hierba', 1, 2, 0.5], ['semilla_trigo', 1, 1, 0.3],
              ['semilla_calabaza', 1, 1, 0.25], ['semilla_chile', 1, 1, 0.12]], xp: 10 },
  // El cuero solo caía de las arañas y los trolls, con suerte: las
  // armaduras de cuero dependían de un botín aleatorio y podías
  // quedarte atascado sin poder fabricar ninguna pieza.
  { id: 'cazadero',  nombre: 'Coto de caza',      icono: '🦌', zona: 'forest', cooldownMs: 150_000,
    descripcion: 'Pieles curtibles de la caza menor.',
    sueltan: [['leather', 3, 5, 1], ['wood', 1, 2, 0.4]], xp: 12 },
  { id: 'colmena',   nombre: 'Colmena silvestre', icono: '🐝', zona: 'forest', cooldownMs: 180_000,
    descripcion: 'Miel para las recetas dulces. Cuidado con las abejas.',
    // Daba de 1 a 3 miel, pero la única receta con miel pide 2: una de
    // cada tres visitas dejaba al jugador esperando 3 minutos de
    // enfriamiento sin poder fabricar nada. El mínimo sube a 2.
    sueltan: [['honey', 2, 4, 1], ['herb', 1, 2, 0.4]], xp: 14 },
  { id: 'lena',      nombre: 'Tocones caídos',   icono: '🪵', zona: 'forest', cooldownMs: 90_000,
    descripcion: 'Madera aprovechable.',
    sueltan: [['wood', 2, 4, 1]], xp: 8 },
  { id: 'trigal',    nombre: 'Trigal silvestre', icono: '🌾', zona: 'pueblo', cooldownMs: 150_000,
    descripcion: 'Trigo y semillas. Lo único que daba trigo antes era nada.',
    sueltan: [['wheat', 2, 4, 1], ['semilla_trigo', 1, 2, 0.6], ['semilla_maiz', 1, 2, 0.45]], xp: 10 },
  { id: 'veta',      nombre: 'Veta de hierro',   icono: '⛏️', zona: 'mines', cooldownMs: 150_000,
    descripcion: 'Mineral de hierro y, con suerte, cristal.',
    sueltan: [['iron_ore', 2, 5, 1], ['crystal', 1, 1, 0.12]], xp: 18 },
  { id: 'charca',    nombre: 'Charca subterránea', icono: '💧', zona: 'mines', cooldownMs: 120_000,
    descripcion: 'Agua de filtración.',
    sueltan: [['water', 4, 7, 1]], xp: 12 },
]
const NODO_POR_ID = new Map(NODOS.map(n => [n.id, n]))

function nodosDeZona(zonaId) {
  const z = zonaCanonica(zonaId)
  return NODOS.filter(n => n.zona === z)
}

function recolectar(char, nodoId) {
  const nodo = NODO_POR_ID.get(nodoId)
  if (!nodo) return { error: 'Ese sitio no existe', code: 404 }

  char.zonesVisited = char.zonesVisited || []
  if (!char.zonesVisited.includes(nodo.zona)) {
    return { error: `Primero tienes que visitar ${ZONES[nodo.zona].name}`, code: 403 }
  }

  char.recoleccion = char.recoleccion || {}
  const listoEn = char.recoleccion[nodoId] || 0
  if (now() < listoEn) {
    return { error: `Ese sitio se está reponiendo (${Math.ceil((listoEn - now()) / 1000)}s)`, code: 429 }
  }
  char.recoleccion[nodoId] = now() + nodo.cooldownMs

  const obtenido = []
  const questUpdates = []
  for (const [itemId, min, max, prob] of nodo.sueltan) {
    if (Math.random() > prob) continue
    const cantidad = randInt(min, max)
    if (!addItem(char, itemId, cantidad, 'recoleccion')) continue   // mochila llena
    obtenido.push({ itemId, cantidad, nombre: template(itemId).name, icono: template(itemId).icon })
    questUpdates.push(...emitProgress(char, `gather_${itemId}`, cantidad))
  }
  char.xp += nodo.xp
  char.recursosRecolectados = (char.recursosRecolectados || 0) + obtenido.reduce((a, o) => a + o.cantidad, 0)
  const levelUps = checkLevelUp(char)
  audit('recolectar', char.name, { nodo: nodoId, obtenido })
  track('recolectar', char.name)
  step(char.name, 'first_gather')
  persist()
  return { success: true, nodo: nodo.nombre, obtenido, xp: nodo.xp, levelUps, questUpdates, listoEn: char.recoleccion[nodoId] }
}

// ── Huerto ─────────────────────────────────────────────────────────
// Cada semilla tarda un tiempo REAL en crecer: se siembra, se cierra
// el juego y al volver está lista. El estado se calcula con marcas de
// tiempo, no con un temporizador en el navegador, así que no se puede
// acelerar desde el cliente.
// Los tiempos se pueden acortar para probar: FARM_SPEED=300 convierte
// cinco minutos de crecimiento en un segundo. En producción vale 1.
const FARM_SPEED = Math.max(1, Number(process.env.FARM_SPEED || 1))
const CULTIVOS = {
  semilla_trigo:  { nombre: 'Semilla de trigo',  icono: '🌾', creceMs: (5 * 60_000) / FARM_SPEED,  produce: 'wheat', min: 3, max: 5, xp: 12,
                    extra: { itemId: 'semilla_trigo', prob: 0.5, min: 1, max: 2 } },
  semilla_hierba: { nombre: 'Semilla de hierba', icono: '🌿', creceMs: (8 * 60_000) / FARM_SPEED,  produce: 'herb',  min: 3, max: 6, xp: 16,
                    extra: { itemId: 'semilla_hierba', prob: 0.5, min: 1, max: 2 } },
  semilla_maiz:    { nombre: 'Semilla de maíz',     icono: '🌽', creceMs: (6 * 60_000) / FARM_SPEED,  produce: 'corn',    min: 3, max: 6, xp: 14,
                     extra: { itemId: 'semilla_maiz', prob: 0.5, min: 1, max: 2 } },
  semilla_calabaza:{ nombre: 'Semilla de calabaza', icono: '🎃', creceMs: (12 * 60_000) / FARM_SPEED, produce: 'pumpkin', min: 2, max: 4, xp: 26,
                     extra: { itemId: 'semilla_calabaza', prob: 0.4, min: 1, max: 1 } },
  semilla_chile:   { nombre: 'Semilla de chile',    icono: '🌶️', creceMs: (18 * 60_000) / FARM_SPEED, produce: 'chili',   min: 2, max: 3, xp: 38,
                     extra: { itemId: 'semilla_chile', prob: 0.35, min: 1, max: 1 } },
  semilla_cristal:{ nombre: 'Esqueje de cristal',icono: '💎', creceMs: (45 * 60_000) / FARM_SPEED, produce: 'crystal', min: 1, max: 2, xp: 60 },
}

const PARCELAS_BASE = 4
function parcelasDe(char) {
  // La casa deja de ser solo decoración: cada nivel da una parcela más.
  return PARCELAS_BASE + Math.max(0, (char.house?.level || 1) - 1)
}

function estadoHuerto(char) {
  char.huerto = char.huerto || []
  const total = parcelasDe(char)
  const parcelas = []
  for (let i = 0; i < total; i++) {
    const p = char.huerto[i]
    if (!p || !p.semilla) { parcelas.push({ i, estado: 'vacia' }); continue }
    const c = CULTIVOS[p.semilla]
    const restante = Math.max(0, p.listoEn - now())
    parcelas.push({
      i, estado: restante > 0 ? 'creciendo' : 'lista',
      semilla: p.semilla, nombre: c.nombre, icono: c.icono,
      produce: template(c.produce).name, iconoProduce: template(c.produce).icon,
      restanteMs: restante,
      progreso: Math.min(1, 1 - restante / c.creceMs),
    })
  }
  return {
    parcelas, total,
    semillas: Object.entries(CULTIVOS).map(([id, c]) => ({
      id, nombre: c.nombre, icono: c.icono, creceMs: c.creceMs,
      produce: template(c.produce).name, tengo: countItem(char, id),
    })),
  }
}

function sembrar(char, indice, semillaId) {
  const c = CULTIVOS[semillaId]
  if (!c) return { error: 'Esa semilla no existe', code: 404 }
  const i = intIn(indice, 0, parcelasDe(char) - 1)
  if (i === null) return { error: 'Parcela inválida', code: 400 }
  char.huerto = char.huerto || []
  if (char.huerto[i] && char.huerto[i].semilla) return { error: 'Esa parcela ya está sembrada', code: 409 }
  if (countItem(char, semillaId) < 1) return { error: `No tienes ${c.nombre}`, code: 400 }
  removeItem(char, semillaId, 1, 'siembra')
  char.huerto[i] = { semilla: semillaId, sembradoEn: now(), listoEn: now() + c.creceMs }
  audit('sembrar', char.name, { parcela: i, semilla: semillaId })
  persist()
  return { success: true, huerto: estadoHuerto(char) }
}

function cosechar(char, indice) {
  const i = intIn(indice, 0, parcelasDe(char) - 1)
  if (i === null) return { error: 'Parcela inválida', code: 400 }
  const p = (char.huerto || [])[i]
  if (!p || !p.semilla) return { error: 'Ahí no hay nada sembrado', code: 400 }
  const c = CULTIVOS[p.semilla]
  if (now() < p.listoEn) {
    return { error: `Todavía está creciendo (${Math.ceil((p.listoEn - now()) / 1000)}s)`, code: 400 }
  }

  const obtenido = []
  const cantidad = randInt(c.min, c.max)
  if (addItem(char, c.produce, cantidad, 'cosecha')) {
    obtenido.push({ itemId: c.produce, cantidad, nombre: template(c.produce).name, icono: template(c.produce).icon })
  }
  // Devolver semillas de vez en cuando evita que el huerto se agote
  if (c.extra && Math.random() < c.extra.prob) {
    const n = randInt(c.extra.min, c.extra.max)
    if (addItem(char, c.extra.itemId, n, 'cosecha')) {
      obtenido.push({ itemId: c.extra.itemId, cantidad: n, nombre: CULTIVOS[c.extra.itemId].nombre, icono: CULTIVOS[c.extra.itemId].icono })
    }
  }
  char.huerto[i] = null
  char.xp += c.xp
  char.cosechas = (char.cosechas || 0) + 1
  char.recursosRecolectados = (char.recursosRecolectados || 0) + obtenido.reduce((a, o) => a + o.cantidad, 0)
  const levelUps = checkLevelUp(char)
  const questUpdates = obtenido.flatMap(o => emitProgress(char, `gather_${o.itemId}`, o.cantidad))
  audit('cosechar', char.name, { parcela: i, obtenido })
  track('cosechar', char.name)
  step(char.name, 'first_harvest')
  persist()
  return { success: true, obtenido, xp: c.xp, levelUps, questUpdates, huerto: estadoHuerto(char) }
}


// ═══════════════════════════════════════════════════════════════════
//  RECURSOS DEL MUNDO — talar, picar y herramientas
//
//  QUÉ RESUELVE
//  Antes, para conseguir madera había que ir al bosque, abrir la barra
//  del huerto y pulsar "reclamar". El recurso aparecía de la nada. Aquí
//  hay un árbol con vida, un hacha equipada y golpes que se la quitan.
//  Cuando cae, la madera entra al inventario de verdad (§7).
//
//  DÓNDE VIVE LA VERDAD
//  Toda en el servidor. El cliente solo dice "golpeo este nodo"; el
//  daño, la vida restante, el botín y el desgaste de la herramienta se
//  calculan aquí. Mandar mil peticiones no hace caer más madera: el
//  nodo tiene la vida que tiene y luego tarda en reaparecer.
//
//  EL HUERTO ANTIGUO NO SE TOCA (§7)
//  Sigue funcionando exactamente igual, en paralelo. Este sistema es
//  otra forma de conseguir materiales, no su sustituto.
//
//  QUÉ AÑADE
//   §8  seis maderas por rareza
//   §9  siete minerales con progresión
//   §10 picos y hachas fabricados con mango + cabeza, donde las
//       estadísticas SALEN de los materiales usados
//   §11 rareza funcional: mejor material, mejores números
//   §4  ranura de herramienta propia, aparte del arma
// ═══════════════════════════════════════════════════════════════════

// El pico y el hacha no ocupan la mano del arma: se llevan a la vez.
if (!SLOTS.includes('tool')) SLOTS.push('tool')

// ── §8 MADERAS ─────────────────────────────────────────────────────
